import glob, os, re, zipfile
TERMS=["food group","station","wellness","nutrition","myplate","poster","festival"]
def docx(p):
    x=zipfile.ZipFile(p).read('word/document.xml').decode('utf8','ignore')
    x=re.sub(r'</w:p>','\n',x)
    return re.sub(r'<[^>]+>','',x)
def pdf(p):
    import fitz
    return chr(10).join(pg.get_text() for pg in fitz.open(p))
def txt(p):
    return open(p,encoding='utf8',errors='ignore').read()
rows=[]
for p in sorted(glob.glob('*/*')):
    e=p.rsplit('.',1)[-1].lower()
    try:
        t=docx(p) if e=='docx' else pdf(p) if e=='pdf' else txt(p) if e in ('html','tsv','xml') else ''
    except Exception:
        t=''
    if not t: continue
    n=sum(t.lower().count(k) for k in TERMS)
    if n: rows.append((n,p))
for n,p in sorted(rows,reverse=True): print(n,p)
PY

